function PlayerInputSwitcher:OnJump()
    if DreamSpaceStates.IsInputForbidden() == true then 
        return
    end
    if self._currentChooseType == JumpHintType.Up then
        self.switchablePlayerController:JumpUp()
    elseif self._currentChooseType == JumpHintType.Forward then
        self.switchablePlayerController:JumpForward()
    elseif self._currentChooseType == JumpHintType.Down then
        self.switchablePlayerController:JumpDown()
    end
end

function PlayerInputSwitcher:OnMeow()
    if DreamSpaceStates.IsInputForbidden() == true then 
        return
    end
    self.switchablePlayerController:Meow()
end


return PlayerInputSwitcher